/* @autogenerated */
package net.civeira.phylax.feature.oauth.consent.infrastructure.driven;

import java.util.List;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

/** The scope approval that approves everything without asking. */
class NoOpScopeApprovalAdapterUnitTest {
  private final NoOpScopeApprovalAdapter approval = new NoOpScopeApprovalAdapter();

  @Test
  @DisplayName("No scope is ever pending of approval")
  void nothing_pending() {
    Assertions.assertEquals(List.of(),
        approval.pendingApprovals("acme", "alice", "web", List.of("openid", "email"), List.of()));
  }

  @Test
  @DisplayName("Storing the approved scopes does nothing")
  void store_does_nothing() {
    Assertions.assertDoesNotThrow(
        () -> approval.storeApprovedScopes("acme", "alice", "web", List.of("openid")));
  }
}
